window.AUTH=window.AUTH||{};window.AUTH["24-556"]={"d":"24-556","id":"2025/24-556","n":"Fernandez v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Joe Fernandez","date":"2025-08-04","url":"https://www.supremecourt.gov/DocketPDF/24/24-556/368811/20250804171506200_24-556%20Brief%20of%20Petitioner.pdf","side":"pet","n":53},{"k":"respondent","label":"Brief of respondent United States","date":"2025-09-25","url":"https://www.supremecourt.gov/DocketPDF/24/24-556/377925/20250925163944602_24-556bsUnitedStates.pdf","side":"res","n":80},{"k":"reply","label":"Reply of petitioner Joe Fernandez","date":"2025-10-27","url":"https://www.supremecourt.gov/DocketPDF/24/24-556/380696/20251027122338934_24-556%20Merits%20Reply%20Brief.pdf","side":"pet","n":24}],"opinion":"https://www.supremecourt.gov/opinions/25pdf/608us2r39_5iek.pdf","tr":true,"items":[{"t":"case","label":"Barclay v. Florida","cite":"463 U.S. 939","y":1983,"id":"1982/81-6908","sc":1,"sum":"The judgment is affirmed. 411 So. 2d 1310, affirmed. JUSTICE REHNQUIST, joined by CHIEF JUSTICE BURGER, JUSTICE WHITE, and JUSTICE O'CONNOR, concluded:","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32"}},{"t":"case","label":"Bostock v. Clayton Cnty.","cite":"590 U.S. 644","y":2020,"id":"2019/17-1618","sc":1,"sum":"The Court held that Title VII of the Civil Rights Act of 1964, which prohibits against employment discrimination “because of . . . sex” encompasses discrimination based on an individual’s sexual orientation.","sumSrc":"Oyez","by":{"0":"26","2":"3"}},{"t":"case","label":"Brady v. Maryland","cite":"373 U.S. 83","y":1963,"id":"1962/490","sc":1,"op":3,"sum":"The Supreme Court held that the prosecution's suppression of evidence violated the Due Process Clause of the Fourteenth Amendment. The Court also held that according the Maryland state law, the confession would not exonerate Brady, so a remand only for reconsidering his punishment was proper.","sumSrc":"Oyez","by":{"0":"41","1":"45"}},{"t":"case","label":"Brogan v. United States","cite":"522 U.S. 398","y":1998,"id":"1997/96-1579","sc":1,"sum":"In a 7-to-2 decision, the Court held that the imposition of criminal liability for false statements is not limited only to those falsehoods that pervert governmental functions - it applies to statements \"of whatever kind.\" Moreover, even if the \"exculpatory no\" doctrine did apply to statements that do not impede federal functions, Brogan would not benefit from it since his falsehoods were intended to prevent federal agents from uncovering the truth.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Concepcion v. United States","cite":"597 U.S. 481","y":2022,"id":"2021/20-1650","sc":1,"op":1,"sum":"Section 404(b) of the First Step Act of 2018, 132 Stat. 5222, allows district courts to consider intervening changes of law or fact in exercising their discretion to reduce a sentence.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"5, 23, 24, 25, 27, 28, 43","1":"43","2":"14, 15"}},{"t":"case","label":"Conn. Nat’l Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23, 28, 35"}},{"t":"case","label":"Dean v. United States","cite":"581 U.S. 62","y":2017,"id":"2016/15-9260","sc":1,"sum":"The Court determined that 18 U.S.C. §924(c) does not prevent a sentencing court from using its discretion to consider the other mandatory minimum sentences a defendant might be facing when calculating an overall appropriate sentence.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Edwards v. Balisok","cite":"520 U.S. 641","y":1997,"id":"1996/95-1352","sc":1,"sum":"The Court held that Balisok's \"claim for declaratory relief and monetary damages, based on allegations of deceit and bias on the part of the decisionmaker that necessarily imply the invalidity of the punishment imposed, is not cognizable....\".","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"584 U.S. 497","y":2018,"id":"2017/16-285","sc":1,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"0":"35","1":"32, 38, 42, 49"}},{"t":"case","label":"Esteras v. United States","cite":"145 S. Ct. 2031","y":2025,"id":"2024/23-7483","sc":1,"op":1,"sum":"A district court considering whether to revoke a defendant’s term of supervised release may not consider 18 U. S. C. §3553(a)(2)(A), which covers retribution vis-à-vis the defendant’s underlying criminal offense.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"27"}},{"t":"case","label":"Heck v. Humphrey","cite":"512 U.S. 477","y":1994,"id":"1993/93-6188","sc":1,"op":1,"ar":1,"sum":"The Supreme Court held that a defendant cannot claim damages for an allegedly unconstitutional conviction or imprisonment without showing that the conviction or sentence has been overturned in some way. The defendant must also exhaust state court remedies before bringing a §1983 action.","sumSrc":"Oyez","by":{"0":"21, 40, 41","2":"21"}},{"t":"case","label":"v Page(s) Herrera v. Collins","cite":"506 U.S. 390","y":1993,"id":"1992/91-7328","sc":1,"op":2,"sum":"The Court held that the rejection of Herrera’s petition did not constitute cruel and unusual punishment under the Eighth Amendment. Chief Justice Rehnquist concluded that evidence of Herrera’s actual innocence was not relevant to his petition for a writ of habeas corpus absent some constitutional violation by the state of Texas.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Hewitt v. United States","cite":"145 S. Ct. 2165","y":2025,"id":"2024/23-1002","sc":1,"sum":"Because a sentence “has . . . been imposed” for purposes of §403(b) of the First Step Act only if the sentence is extant (i.e., has not been vacated), the Act’s more lenient penalties apply to defendants whose previous 18 U. S. C. §924(c) sentences have been vacated and who need to be resentenced following the Act’s enactment; the judgment of the Fifth Circuit is reversed and the case is remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"37"}},{"t":"case","label":"J.E.M. Ag Supply, Inc. v. Pioneer Hi-Bred Int’l, Inc.","cite":"534 U.S. 124","y":2001,"id":"2001/99-1996","sc":1,"sum":"The Court held that utility patents may be issued for plants.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"Kimbrough v. United States","cite":"552 U.S. 85","y":2007,"id":"2007/06-6330","sc":1,"sum":"Justice Ruth Bader Ginsburg authored the Court's 7-2 majority opinion reversing the Fourth Circuit and affirming the sentence handed down by the trial judge. Ginsburg noted that the drug trafficking statute still had some minimum sentencing requirements, and expressed the Court's confidence that district courts could maintain reasonably uniform approaches to cocaine sentencing.","sumSrc":"Oyez","by":{"0":"5, 23, 27, 28","2":"14"}},{"t":"case","label":"Koon v. United States","cite":"518 U.S. 81","y":1996,"id":"1995/94-1664","sc":1,"sum":"The Court held that the Court of Appeals should not review de novo a decision to depart from the Guideline sentencing range, but instead should ask whether the sentencing court abused its discretion.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Lomax v. Ortiz-Marquez","cite":"590 U.S. 595","y":2020,"id":"2019/18-8369","sc":1,"sum":"The Court held that a dismissal without prejudice for failure to state a claim counts as a strike under the Prison Litigation Reform Act, 28 U.S.C. § 1915(g), which bars inmates from filing or appealing a federal civil action without paying the associated fees if they have filed three or more cases or appeals that were dismissed because the lawsuits were frivolous or malicious or did not properly state a legal claim for relief.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Matsushita Elec. Indus. Co. v. Epstein","cite":"516 U.S. 367","y":1996,"id":"1995/94-1809","sc":1,"sum":"The Court held that, absent a partial repeal of the Full Faith and Credit Act by another federal statute, a federal court must give the judgment the same effect that it would have in the courts of the State in which it was rendered.","sumSrc":"Oyez","by":{"0":"35","2":"19"}},{"t":"case","label":"McQuiggin v. Perkins","cite":"569 U.S. 383","y":2013,"id":"2012/12-126","sc":1,"op":2,"sum":"The Court held that proving actual innocence allows a petitioner to pursue habeas corpus relief regardless of a statute of limitations.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Nelson v. Campbell","cite":"541 U.S. 637","y":2004,"id":"2003/03-6821","sc":1,"sum":"The Court ruled unanimously that Nelson's suit dealt only with the proposed method of execution, not with his conviction or sentence, and was therefore different from a habeas corpus appeal. Nelson had a right to challenge the necessity of the procedure for his execution using the same legal approach he would have used to challenge the conditions of his prison.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Pepper v. United States","cite":"562 U.S. 476","y":2011,"id":"2010/09-6822","sc":1,"sum":"The Court held that when a defendant's sentence has been set aside on appeal, a district court may consider evidence of the defendant's rehabilitation after the initial sentences, which may support lesser sentencing guidelines.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Preiser v. Rodriguez","cite":"411 U.S. 475","y":1973,"id":"1972/71-1369","sc":1,"op":29,"ar":2,"sum":"When a state prisoner challenges the fact or duration of his physical imprisonment and by way of relief seeks a determination that he is entitled to immediate release or a speedier release, his sole federal remedy is a writ of habeas corpus.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"7, 20, 36, 39, 40, 43","1":"36, 37","2":"3, 4, 20, 21"}},{"t":"case","label":"RadLAX Gateway Hotel, LLC v. Amalgamated Bank","cite":"566 U.S. 639","y":2012,"id":"2011/11-166","sc":1,"sum":"The Court held that a company could not obtain confirmation of a Chapter 11 bankruptcy plan that provided for the sale of its assets free from lien without permitting a bank to credit-bid at the sale.","sumSrc":"Oyez","by":{"0":"44, 46","1":"38"}},{"t":"case","label":"vi Page(s) Setser v. United States","cite":"566 U.S. 231","y":2012,"id":"2011/10-7387","sc":1,"op":1,"sum":"Explaining that § 3582(c)(1)(A) provides for relief when “ `developments that take place after the frst sentencing' produc[e] unfairness to the defendant” (citation omitted).","sumSrc":"opinion","by":{"0":"33, 34","1":"46"}},{"t":"case","label":"Strickland v. Washington","cite":"466 U.S. 668","y":1984,"id":"1983/82-1554","sc":1,"op":2,"sum":"The Supreme Court held that: (1) counsel's performance must be deficient; and (2) the deficient performance must have prejudiced the defense so as to deprive the defendant of a fair trial.","sumSrc":"Oyez","by":{"0":"41","1":"45"}},{"t":"case","label":"Taylor v. United States","cite":"495 U.S. 575","y":1990,"id":"1989/88-7194","sc":1,"sum":"An offense constitutes \"burglary\" under §924(e) if, regardless of its exact definition or label, it has the basic elements of a \"generic\" burglary-i. e., an unlawful or unprivileged entry into, or remaining in, a building or other structure, with intent to commit a crime-or if the charging paper and jury instructions actually required the jury to find all the elements of generic burglary in order to convict the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47"}},{"t":"case","label":"United States v. Brooker","cite":"976 F.3d 228","y":2020,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/976/228/","by":{"0":"14, 15, 28","1":"8"}},{"t":"case","label":"United States v. Davis","cite":"588 U.S. 445","y":2019,"id":"2018/18-431","sc":1,"op":1,"sum":"Title 18 U. S. C. §924(c)(3)(B), which provides enhanced penalties for using a firearm during a “crime of violence,” is unconstitutionally vague.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"13","1":"12"}},{"t":"case","label":"United States v. Granderson","cite":"511 U.S. 39","y":1994,"id":"1993/92-1662","sc":1,"sum":"The Court held 7-2 that the U.S. Code's section 3565 refers to the original sentence range set by U.S. Sentencing Guidelines. Therefore, the minimum revocation sentence for drug possession while on probation is one third the maximum of the Guidelines range of imprisonment; the maximum revocation sentence is the Guidelines maximum.","sumSrc":"Oyez","by":{"0":"46"}},{"t":"case","label":"United States v. Jenkins","cite":"50 F.4th 1185","y":2022,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/50/1185/","op":1,"by":{"0":"43","1":"25-27, 34","2":"13"}},{"t":"case","label":"United States v. McCall","cite":"56 F.4th 1048","y":2022,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/56/1048/","by":{"0":"26","1":"35, 39, 44"}},{"t":"case","label":"United States v. R.L.C.","cite":"503 U.S. 291","y":1992,"id":"1991/90-1577","sc":1,"sum":"The judgment is affirmed. 915 F. 2d 320, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47"}},{"t":"case","label":"United States v. Shkambi","cite":"993 F.3d 388","y":2021,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/993/388/","by":{"0":"28"}},{"t":"case","label":"United States v. Tucker","cite":"404 U.S. 443","y":1972,"id":"1971/70-86","sc":1,"sum":"Under these circumstances the Court of Appeals was correct in remanding the case to the District Court for reconsideration of the sentence imposed upon the defendant. Pp. 446-449. 431 F. 2d 1292, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"vii Page(s) Wasman v. United States","cite":"468 U.S. 559","y":1984,"id":"1983/83-173","sc":1,"sum":"After retrial and conviction following a defendant's successful appeal, a sentencing authority may justify an increased sentence by affirmatively identifying relevant conduct or events that occurred subsequent to the original sentencing proceedings. Pp. 563-565, 569-571, 571-572.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Wilkinson v. Dotson","cite":"544 U.S. 74","y":2005,"id":"2004/03-287","sc":1,"op":1,"sum":"Yes and No. In an 8-1 decision, the Court affirmed the appellate court and ruled that prisoners could use Section 1983 to challenge a state's parole procedures.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Williams v. New York","cite":"337 U.S. 241","y":1949,"id":"scdb/1948-087","sc":1,"sum":"The Due Process Clause of the Fourteenth Amendment does not require that a person convicted after a fair trial be confronted with and permitted to cross-examine witnesses as to his prior criminal record considered by the judge in accordance with a state statute in determining what sentence to impose pursuant to broad discretion vested in him under state law-even when the jury recommends life imprisonment and the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Wisconsin v. Mitchell","cite":"508 U.S. 476","y":1993,"id":"1992/92-515","sc":1,"sum":"The Court found that the Wisconsin statute paralleled antidiscrimination laws which had been found to comply with the First Amendment. It also determined that the consequences for the victim and the community tended to be more severe, when the victim of a crime was chosen on account of his or her race.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Wooden v. United States","cite":"595 U.S. 360","y":2022,"id":"2021/20-5279","sc":1,"sum":"Wooden’s ten burglary offenses arising from a single criminal episode did not occur on different “occasions” and thus count as only one prior conviction under the Armed Career Criminal Act.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"47"}},{"t":"usc","label":"18 U.S.C. § 3582","url":"https://www.law.cornell.edu/uscode/text/18/3582","subs":["(c)","(c)(1)(A)","(c)(1)(A)(i)","(d)","(d)(2)(A)","(d)(2)(B)","(d)(2)(C)"],"stext":{"head":"§3582. Imposition of a sentence of imprisonment","paras":[[0,"(a) Factors To Be Considered in Imposing a Term of Imprisonment.—The court, in determining whether to impose a term of imprisonment, and, if a term of imprisonment is to be imposed, in determining the length of the term, shall consider the factors set forth in section 3553(a) to the extent that they are applicable, recognizing that imprisonment is not an appropriate means of promoting correction and rehabilitation. In determining whether to make a recommendation concerning the type of prison facility appropriate for the defendant, the court shall consider any pertinent policy statements issued by the Sentencing Commission pursuant to 28 U.S.C. 994(a)(2)."],[0,"(b) Effect of Finality of Judgment.—Notwithstanding the fact that a sentence to imprisonment can subsequently be—"],[1,"(1) modified pursuant to the provisions of subsection (c);"],[1,"(2) corrected pursuant to the provisions of rule 35 of the Federal Rules of Criminal Procedure and section 3742; or"],[1,"(3) appealed and modified, if outside the guideline range, pursuant to the provisions of section 3742;"],[0,"a judgment of conviction that includes such a sentence constitutes a final judgment for all other purposes."],[0,"(c) Modification of an Imposed Term of Imprisonment.—The court may not modify a term of imprisonment once it has been imposed except that—"],[1,"(1) in any case—"],[2,"(A) the court, upon motion of the Director of the Bureau of Prisons, or upon motion of the defendant after the defendant has fully exhausted all administrative rights to appeal a failure of the Bureau of Prisons to bring a motion on the defendant's behalf or the lapse of 30 days from the receipt of such a request by the warden of the defendant's facility, whichever is earlier, may reduce the term of imprisonment (and may impose a term of probation or supervised release with or without conditions that does not exceed the unserved portion of the original term of imprisonment), after considering the factors set forth in section 3553(a) to the extent that they are applicable, if it finds that—"],[3,"(i) extraordinary and compelling reasons warrant such a reduction; or"],[3,"(ii) the defendant is at least 70 years of age, has served at least 30 years in prison, pursuant to a sentence imposed under section 3559(c), for the offense or offenses for which the defendant is currently imprisoned, and a determination has been made by the Director of the Bureau of Prisons that the defendant is not a danger to the safety of any other person or the community, as provided under section 3142(g);"],[2,"and that such a reduction is consistent with applicable policy statements issued by the Sentencing Commission; and"],[2,"(B) the court may modify an imposed term of imprisonment to the extent otherwise expressly permitted by statute or by Rule 35 of the Federal Rules of Criminal Procedure; and"],[1,"(2) in the case of a defendant who has been sentenced to a term of imprisonment based on a sentencing range that has subsequently been lowered by the Sentencing Commission pursuant to 28 U.S.C. 994(o), upon motion of the defendant or the Director of the Bureau of Prisons, or on its own motion, the court may reduce the term of imprisonment, after considering the factors set forth in section 3553(a) to the extent that they are applicable, if such a reduction is consistent with applicable policy statements issued by the Sentencing Commission."],[0,"(d) Notification Requirements.—"],[1,"(1) Terminal illness defined.—In this subsection, the term \"terminal illness\" means a disease or condition with an end-of-life trajectory."],[1,"(2) Notification.—The Bureau of Prisons shall, subject to any applicable confidentiality requirements—"],[2,"(A) in the case of a defendant diagnosed with a terminal illness—"],[3,"(i) not later than 72 hours after the diagnosis notify the defendant's attorney, partner, and family members of the defendant's condition and inform the defendant's attorney, partner, and family members that they may prepare and submit on the defendant's behalf a request for a sentence reduction pursuant to subsection (c)(1)(A);"],[3,"(ii) not later than 7 days after the date of the diagnosis, provide the defendant's partner and family members (including extended family) with an opportunity to visit the defendant in person;"],[3,"(iii) upon request from the defendant or his attorney, partner, or a family member, ensure that Bureau of Prisons employees assist the defendant in the preparation, drafting, and submission of a request for a sentence reduction pursuant to subsection (c)(1)(A); and"],[3,"(iv) not later than 14 days of receipt of a request for a sentence reduction submitted on the defendant's behalf by the defendant or the defendant's attorney, partner, or family member, process the request;"],[2,"(B) in the case of a defendant who is physically or mentally unable to submit a request for a sentence reduction pursuant to subsection (c)(1)(A)—"],[3,"(i) inform the defendant's attorney, partner, and family members that they may prepare and submit on the defendant's behalf a request for a sentence reduction pursuant to subsection (c)(1)(A);"],[3,"(ii) accept and process a request for sentence reduction that has been prepared and submitted on the defendant's behalf by the defendant's attorney, partner, or family member under clause (i); and"],[3,"(iii) upon request from the defendant or his attorney, partner, or family member, ensure that Bureau of Prisons employees assist the defendant in the preparation, drafting, and submission of a request for a sentence reduction pursuant to subsection (c)(1)(A); and"],[2,"(C) ensure that all Bureau of Prisons facilities regularly and visibly post, including in prisoner handbooks, staff training materials, and facility law libraries and medical and hospice facilities, and make available to prisoners upon demand, notice of—"],[3,"(i) a defendant's ability to request a sentence reduction pursuant to subsection (c)(1)(A);"],[3,"(ii) the procedures and timelines for initiating and resolving requests described in clause (i); and"],[3,"(iii) the right to appeal a denial of a request described in clause (i) after all administrative rights to appeal within the Bureau of Prisons have been exhausted."],[1,"(3) Annual report.—Not later than 1 year after December 21, 2018, and once every year thereafter, the Director of the Bureau of Prisons shall submit to the Committee on the Judiciary of the Senate and the Committee on the Judiciary of the House of Representatives a report on requests for sentence reductions pursuant to subsection (c)(1)(A), which shall include a description of, for the previous year—"],[2,"(A) the number of prisoners granted and denied sentence reductions, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(B) the number of requests initiated by or on behalf of prisoners, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(C) the number of requests that Bureau of Prisons employees assisted prisoners in drafting, preparing, or submitting, categorized by the criteria relied on as the grounds for a reduction in sentence, and the final decision made in each request;"],[2,"(D) the number of requests that attorneys, partners, or family members submitted on a defendant's behalf, categorized by the criteria relied on as the grounds for a reduction in sentence, and the final decision made in each request;"],[2,"(E) the number of requests approved by the Director of the Bureau of Prisons, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(F) the number of requests denied by the Director of the Bureau of Prisons and the reasons given for each denial, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(G) for each request, the time elapsed between the date the request was received by the warden and the final decision, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(H) for each request, the number of prisoners who died while their request was pending and, for each, the amount of time that had elapsed between the date the request was received by the Bureau of Prisons, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(I) the number of Bureau of Prisons notifications to attorneys, partners, and family members of their right to visit a terminally ill defendant as required under paragraph (2)(A)(ii) and, for each, whether a visit occurred and how much time elapsed between the notification and the visit;"],[2,"(J) the number of visits to terminally ill prisoners that were denied by the Bureau of Prisons due to security or other concerns, and the reasons given for each denial; and"],[2,"(K) the number of motions filed by defendants with the court after all administrative rights to appeal a denial of a sentence reduction had been exhausted, the outcome of each motion, and the time that had elapsed between the date the request was first received by the Bureau of Prisons and the date the defendant filed the motion with the court."],[0,"(e) Inclusion of an Order To Limit Criminal Association of Organized Crime and Drug Offenders.—The court, in imposing a sentence to a term of imprisonment upon a defendant convicted of a felony set forth in chapter 95 (racketeering) or 96 (racketeer influenced and corrupt organizations) of this title or in the Comprehensive Drug Abuse Prevention and Control Act of 1970 (21 U.S.C. 801 et seq.), or at any time thereafter upon motion by the Director of the Bureau of Prisons or a United States attorney, may include as a part of the sentence an order that requires that the defendant not associate or communicate with a specified person, other than his attorney, upon a showing of probable cause to believe that association or communication with such person is for the purpose of enabling the defendant to control, manage, direct, finance, or otherwise participate in an illegal enterprise."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3582?type=usc&year=mostrecent&link-type=html"},"op":18,"ar":4,"head":"§3582. Imposition of a sentence of imprisonment","tname":"Crimes and Criminal Procedure","by":{"0":"2, 4, 7, 8, 9, 16, 17, 21, 25","1":"4, 10, 12, 13, 22, 4, 10, 12, 13, 22, 4, 10, 12, 13, 22, 4, 10, 12, 13, 22, 4, 10, 12, 13, 22, 4, 10, 12, 13, 22, 4, 10, 12, 13, 22, 4, 10, 12, 13, 22","2":"1-6, 8, 10, 12-24"}},{"t":"usc","label":"18 U.S.C. § 3584","url":"https://www.law.cornell.edu/uscode/text/18/3584","by":{"0":"33"}},{"t":"usc","label":"18 U.S.C. § 3661","url":"https://www.law.cornell.edu/uscode/text/18/3661","by":{"0":"25"}},{"t":"usc","label":"28 U.S.C. § 994","url":"https://www.law.cornell.edu/uscode/text/28/994","subs":["(t)"],"stext":{"head":"§994. Duties of the Commission","paras":[[0,"(a) The Commission, by affirmative vote of at least four members of the Commission, and pursuant to its rules and regulations and consistent with all pertinent provisions of any Federal statute shall promulgate and distribute to all courts of the United States and to the United States Probation System—"],[1,"(1) guidelines, as described in this section, for use of a sentencing court in determining the sentence to be imposed in a criminal case, including—"],[2,"(A) a determination whether to impose a sentence to probation, a fine, or a term of imprisonment;"],[2,"(B) a determination as to the appropriate amount of a fine or the appropriate length of a term of probation or a term of imprisonment;"],[2,"(C) a determination whether a sentence to a term of imprisonment should include a requirement that the defendant be placed on a term of supervised release after imprisonment, and, if so, the appropriate length of such a term;"],[2,"(D) a determination whether multiple sentences to terms of imprisonment should be ordered to run concurrently or consecutively; and"],[2,"(E) a determination under paragraphs (6) and (11) 1 of section 3563(b) of title 18;"],[1,"(2) general policy statements regarding application of the guidelines or any other aspect of sentencing or sentence implementation that in the view of the Commission would further the purposes set forth in section 3553(a)(2) of title 18, United States Code, including the appropriate use of—"],[2,"(A) the sanctions set forth in sections 3554, 3555, and 3556 of title 18;"],[2,"(B) the conditions of probation and supervised release set forth in sections 3563(b) and 3583(d) of title 18;"],[2,"(C) the sentence modification provisions set forth in sections 3563(c), 3564, 3573, and 3582(c) of title 18;"],[2,"(D) the fine imposition provisions set forth in section 3572 of title 18;"],[2,"(E) the authority granted under rule 11(e)(2) of the Federal Rules of Criminal Procedure to accept or reject a plea agreement entered into pursuant to rule 11(e)(1); and"],[2,"(F) the temporary release provisions set forth in section 3622 of title 18, and the prerelease custody provisions set forth in section 3624(c) of title 18; and"],[1,"(3) guidelines or general policy statements regarding the appropriate use of the provisions for revocation of probation set forth in section 3565 of title 18, and the provisions for modification of the term or conditions of supervised release and revocation of supervised release set forth in section 3583(e) of title 18."],[0,"(b)(1) The Commission, in the guidelines promulgated pursuant to subsection (a)(1), shall, for each category of offense involving each category of defendant, establish a sentencing range that is consistent with all pertinent provisions of title 18, United States Code."],[0,"(2) If a sentence specified by the guidelines includes a term of imprisonment, the maximum of the range established for such a term shall not exceed the minimum of that range by more than the greater of 25 percent or 6 months, except that, if the minimum term of the range is 30 years or more, the maximum may be life imprisonment."],[0,"(c) The Commission, in establishing categories of offenses for use in the guidelines and policy statements governing the imposition of sentences of probation, a fine, or imprisonment, governing the imposition of other authorized sanctions, governing the size of a fine or the length of a term of probation, imprisonment, or supervised release, and governing the conditions of probation, supervised release, or imprisonment, shall consider whether the following matters, among others, have any relevance to the nature, extent, place of service, or other incidents 2 of an appropriate sentence, and shall take them into account only to the extent that they do have relevance—"],[1,"(1) the grade of the offense;"],[1,"(2) the circumstances under which the offense was committed which mitigate or aggravate the seriousness of the offense;"],[1,"(3) the nature and degree of the harm caused by the offense, including whether it involved property, irreplaceable property, a person, a number of persons, or a breach of public trust;"],[1,"(4) the community view of the gravity of the offense;"],[1,"(5) the public concern generated by the offense;"],[1,"(6) the deterrent effect a particular sentence may have on the commission of the offense by others; and"],[1,"(7) the current incidence of the offense in the community and in the Nation as a whole."],[0,"(d) The Commission in establishing categories of defendants for use in the guidelines and policy statements governing the imposition of sentences of probation, a fine, or imprisonment, governing the imposition of other authorized sanctions, governing the size of a fine or the length of a term of probation, imprisonment, or supervised release, and governing the conditions of probation, supervised release, or imprisonment, shall consider whether the following matters, among others, with respect to a defendant, have any relevance to the nature, extent, place of service, or other incidents 2 of an appropriate sentence, and shall take them into account only to the extent that they do have relevance—"],[1,"(1) age;"],[1,"(2) education;"],[1,"(3) vocational skills;"],[1,"(4) mental and emotional condition to the extent that such condition mitigates the defendant's culpability or to the extent that such condition is otherwise plainly relevant;"],[1,"(5) physical condition, including drug dependence;"],[1,"(6) previous employment record;"],[1,"(7) family ties and responsibilities;"],[1,"(8) community ties;"],[1,"(9) role in the offense;"],[1,"(10) criminal history; and"],[1,"(11) degree of dependence upon criminal activity for a livelihood."],[0,"The Commission shall assure that the guidelines and policy statements are entirely neutral as to the race, sex, national origin, creed, and socioeconomic status of offenders."],[0,"(e) The Commission shall assure that the guidelines and policy statements, in recommending a term of imprisonment or length of a term of imprisonment, reflect the general inappropriateness of considering the education, vocational skills, employment record, family ties and responsibilities, and community ties of the defendant."],[0,"(f) The Commission, in promulgating guidelines pursuant to subsection (a)(1), shall promote the purposes set forth in section 991(b)(1), with particular attention to the requirements of subsection 991(b)(1)(B) for providing certainty and fairness in sentencing and reducing unwarranted sentence disparities."],[0,"(g) The Commission, in promulgating guidelines pursuant to subsection (a)(1) to meet the purposes of sentencing as set forth in section 3553(a)(2) of title 18, United States Code, shall take into account the nature and capacity of the penal, correctional, and other facilities and services available, and shall make recommendations concerning any change or expansion in the nature or capacity of such facilities and services that might become necessary as a result of the guidelines promulgated pursuant to the provisions of this chapter. The sentencing guidelines prescribed under this chapter shall be formulated to minimize the likelihood that the Federal prison population will exceed the capacity of the Federal prisons, as determined by the Commission."],[0,"(h) The Commission shall assure that the guidelines specify a sentence to a term of imprisonment at or near the maximum term authorized for categories of defendants in which the defendant is eighteen years old or older and—"],[1,"(1) has been convicted of a felony that is—"],[2,"(A) a crime of violence; or"],[2,"(B) an offense described in section 401 of the Controlled Substances Act (21 U.S.C. 841), sections 1002(a), 1005, and 1009 of the Controlled Substances Import and Export Act (21 U.S.C. 952(a), 955, and 959), and chapter 705 of title 46; and"],[1,"(2) has previously been convicted of two or more prior felonies, each of which is—"],[2,"(A) a crime of violence; or"],[2,"(B) an offense described in section 401 of the Controlled Substances Act (21 U.S.C. 841), sections 1002(a), 1005, and 1009 of the Controlled Substances Import and Export Act (21 U.S.C. 952(a), 955, and 959), and chapter 705 of title 46."],[0,"(i) The Commission shall assure that the guidelines specify a sentence to a substantial term of imprisonment for categories of defendants in which the defendant—"],[1,"(1) has a history of two or more prior Federal, State, or local felony convictions for offenses committed on different occasions;"],[1,"(2) committed the offense as part of a pattern of criminal conduct from which the defendant derived a substantial portion of the defendant's income;"],[1,"(3) committed the offense in furtherance of a conspiracy with three or more persons engaging in a pattern of racketeering activity in which the defendant participated in a managerial or supervisory capacity;"],[1,"(4) committed a crime of violence that constitutes a felony while on release pending trial, sentence, or appeal from a Federal, State, or local felony for which he was ultimately convicted; or"],[1,"(5) committed a felony that is set forth in section 401 or 1010 of the Comprehensive Drug Abuse Prevention and Control Act of 1970 (21 U.S.C. 841 and 960), and that involved trafficking in a substantial quantity of a controlled substance."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/994?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§994. Duties of the Commission","tname":"Judiciary and Judicial Procedure","by":{"0":"4, 8, 27, 28","1":"4, 10, 12, 13, 22","2":"2, 11"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"0":"1"}},{"t":"usc","label":"28 U.S.C. § 2253","url":"https://www.law.cornell.edu/uscode/text/28/2253","by":{"0":"10"}},{"t":"usc","label":"28 U.S.C. § 2254","url":"https://www.law.cornell.edu/uscode/text/28/2254","stext":{"head":"§2254. State custody; remedies in Federal courts","paras":[[0,"(a) The Supreme Court, a Justice thereof, a circuit judge, or a district court shall entertain an application for a writ of habeas corpus in behalf of a person in custody pursuant to the judgment of a State court only on the ground that he is in custody in violation of the Constitution or laws or treaties of the United States."],[0,"(b)(1) An application for a writ of habeas corpus on behalf of a person in custody pursuant to the judgment of a State court shall not be granted unless it appears that—"],[1,"(A) the applicant has exhausted the remedies available in the courts of the State; or"],[1,"(B)(i) there is an absence of available State corrective process; or"],[1,"(ii) circumstances exist that render such process ineffective to protect the rights of the applicant."],[0,"(2) An application for a writ of habeas corpus may be denied on the merits, notwithstanding the failure of the applicant to exhaust the remedies available in the courts of the State."],[0,"(3) A State shall not be deemed to have waived the exhaustion requirement or be estopped from reliance upon the requirement unless the State, through counsel, expressly waives the requirement."],[0,"(c) An applicant shall not be deemed to have exhausted the remedies available in the courts of the State, within the meaning of this section, if he has the right under the law of the State to raise, by any available procedure, the question presented."],[0,"(d) An application for a writ of habeas corpus on behalf of a person in custody pursuant to the judgment of a State court shall not be granted with respect to any claim that was adjudicated on the merits in State court proceedings unless the adjudication of the claim—"],[1,"(1) resulted in a decision that was contrary to, or involved an unreasonable application of, clearly established Federal law, as determined by the Supreme Court of the United States; or"],[1,"(2) resulted in a decision that was based on an unreasonable determination of the facts in light of the evidence presented in the State court proceeding."],[0,"(e)(1) In a proceeding instituted by an application for a writ of habeas corpus by a person in custody pursuant to the judgment of a State court, a determination of a factual issue made by a State court shall be presumed to be correct. The applicant shall have the burden of rebutting the presumption of correctness by clear and convincing evidence."],[0,"(2) If the applicant has failed to develop the factual basis of a claim in State court proceedings, the court shall not hold an evidentiary hearing on the claim unless the applicant shows that—"],[1,"(A) the claim relies on—"],[2,"(i) a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable; or"],[2,"(ii) a factual predicate that could not have been previously discovered through the exercise of due diligence; and"],[1,"(B) the facts underlying the claim would be sufficient to establish by clear and convincing evidence that but for constitutional error, no reasonable factfinder would have found the applicant guilty of the underlying offense."],[0,"(f) If the applicant challenges the sufficiency of the evidence adduced in such State court proceeding to support the State court's determination of a factual issue made therein, the applicant, if able, shall produce that part of the record pertinent to a determination of the sufficiency of the evidence to support such determination. If the applicant, because of indigency or other reason is unable to produce such part of the record, then the State shall produce such part of the record and the Federal court shall direct the State to do so by order directed to an appropriate State official. If the State cannot provide such pertinent part of the record, then the court shall determine under the existing facts and circumstances what weight shall be given to the State court's factual determination."],[0,"(g) A copy of the official records of the State court, duly certified by the clerk of such court to be a true and correct copy of a finding, judicial opinion, or other reliable written indicia showing such a factual determination by the State court shall be admissible in the Federal court proceeding."],[0,"(h) Except as provided in section 408 of the Controlled Substances Act, in all proceedings brought under this section, and any subsequent proceedings on review, the court may appoint counsel for an applicant who is or becomes financially unable to afford counsel, except as provided by a rule promulgated by the Supreme Court pursuant to statutory authority. Appointment of counsel under this section shall be governed by section 3006A of title 18."],[0,"(i) The ineffectiveness or incompetence of counsel during Federal or State collateral post-conviction proceedings shall not be a ground for relief in a proceeding arising under section 2254."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2254?type=usc&year=mostrecent&link-type=html"},"op":13,"head":"§2254. State custody; remedies in Federal courts","tname":"Judiciary and Judicial Procedure","by":{"0":"39","1":"36, 37"}},{"t":"usc","label":"28 U.S.C. § 2255","url":"https://www.law.cornell.edu/uscode/text/28/2255","subs":["(a)","(b)","(e)","(h)"],"stext":{"head":"§2255. Federal custody; remedies on motion attacking sentence","paras":[[0,"(a) A prisoner in custody under sentence of a court established by Act of Congress claiming the right to be released upon the ground that the sentence was imposed in violation of the Constitution or laws of the United States, or that the court was without jurisdiction to impose such sentence, or that the sentence was in excess of the maximum authorized by law, or is otherwise subject to collateral attack, may move the court which imposed the sentence to vacate, set aside or correct the sentence."],[0,"(b) Unless the motion and the files and records of the case conclusively show that the prisoner is entitled to no relief, the court shall cause notice thereof to be served upon the United States attorney, grant a prompt hearing thereon, determine the issues and make findings of fact and conclusions of law with respect thereto. If the court finds that the judgment was rendered without jurisdiction, or that the sentence imposed was not authorized by law or otherwise open to collateral attack, or that there has been such a denial or infringement of the constitutional rights of the prisoner as to render the judgment vulnerable to collateral attack, the court shall vacate and set the judgment aside and shall discharge the prisoner or resentence him or grant a new trial or correct the sentence as may appear appropriate."],[0,"(c) A court may entertain and determine such motion without requiring the production of the prisoner at the hearing."],[0,"(d) An appeal may be taken to the court of appeals from the order entered on the motion as from a final judgment on application for a writ of habeas corpus."],[0,"(e) An application for a writ of habeas corpus in behalf of a prisoner who is authorized to apply for relief by motion pursuant to this section, shall not be entertained if it appears that the applicant has failed to apply for relief, by motion, to the court which sentenced him, or that such court has denied him relief, unless it also appears that the remedy by motion is inadequate or ineffective to test the legality of his detention."],[0,"(f) A 1-year period of limitation shall apply to a motion under this section. The limitation period shall run from the latest of—"],[1,"(1) the date on which the judgment of conviction becomes final;"],[1,"(2) the date on which the impediment to making a motion created by governmental action in violation of the Constitution or laws of the United States is removed, if the movant was prevented from making a motion by such governmental action;"],[1,"(3) the date on which the right asserted was initially recognized by the Supreme Court, if that right has been newly recognized by the Supreme Court and made retroactively applicable to cases on collateral review; or"],[1,"(4) the date on which the facts supporting the claim or claims presented could have been discovered through the exercise of due diligence."],[0,"(g) Except as provided in section 408 of the Controlled Substances Act, in all proceedings brought under this section, and any subsequent proceedings on review, the court may appoint counsel, except as provided by a rule promulgated by the Supreme Court pursuant to statutory authority. Appointment of counsel under this section shall be governed by section 3006A of title 18."],[0,"(h) A second or successive motion must be certified as provided in section 2244 by a panel of the appropriate court of appeals to contain—"],[1,"(1) newly discovered evidence that, if proven and viewed in light of the evidence as a whole, would be sufficient to establish by clear and convincing evidence that no reasonable factfinder would have found the movant guilty of the offense; or"],[1,"(2) a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2255?type=usc&year=mostrecent&link-type=html"},"op":57,"ar":15,"head":"§2255. Federal custody; remedies on motion attacking sentence","tname":"Judiciary and Judicial Procedure","by":{"0":"3, 4, 9, 10, 20, 36, 38, 44, 46","1":"36, 37, 36, 37, 36, 37, 36, 37, 36, 37, 36, 37","2":"1-9, 11, 12, 15-17, 19-24"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","stext":{"head":"§1983. Civil action for deprivation of rights","paras":[[0,"Every person who, under color of any statute, ordinance, regulation, custom, or usage, of any State or Territory or the District of Columbia, subjects, or causes to be subjected, any citizen of the United States or other person within the jurisdiction thereof to the deprivation of any rights, privileges, or immunities secured by the Constitution and laws, shall be liable to the party injured in an action at law, suit in equity, or other proper proceeding for redress, except that in any action brought against a judicial officer for an act or omission taken in such officer's judicial capacity, injunctive relief shall not be granted unless a declaratory decree was violated or declaratory relief was unavailable. For the purposes of this section, any Act of Congress applicable exclusively to the District of Columbia shall be considered to be a statute of the District of Columbia."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1983?type=usc&year=mostrecent&link-type=html"},"op":19,"head":"§1983. Civil action for deprivation of rights","tname":"The Public Health and Welfare","by":{"0":"7, 39","1":"36, 37"}},{"t":"law","label":"Pub. L. No. 80-773","by":{"0":"9"}},{"t":"law","label":"Pub. L. No. 104-132","url":"https://www.govinfo.gov/link/plaw/104/public/132","by":{"0":"10"}},{"t":"law","label":"Pub. L. No. 98-473","url":"https://www.govinfo.gov/link/statute/98/1837","by":{"0":"7, 8, 30, 32"}},{"t":"law","label":"Pub. L. No. 115-391","url":"https://www.govinfo.gov/link/plaw/115/public/391","by":{"0":"9, 32","1":"7"}},{"t":"case","label":"Berman v. United States","cite":"302 U.S. 211","y":1937,"id":"scdb/1937-024","sc":1,"sum":"1. The sentence in a criminal case is the final judgment.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Bifulco v. United States","cite":"447 U.S. 381","y":1980,"id":"1979/79-5010","sc":1,"sum":"Section 406 of the Act does not authorize the imposition of a special parole term even though that sanction is included within the penalty provision of the target offense.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"48"}},{"t":"case","label":"Bousley v. United States","cite":"523 U.S. 614","y":1998,"id":"1997/96-8516","sc":1,"sum":"The Court held that, although Bousley's claim was procedurally defaulted, Bousley may be entitled to a hearing on the merits of it if he makes the necessary showing to relieve the default.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"Bray v. The Atalanta","cite":"4 F. Cas. 37","y":1794,"court":"D.S.C.","url":"https://www.courtlistener.com/c/F.%20Cas./4/37/","by":{"1":"48"}},{"t":"case","label":"Brown v. United States","cite":"602 U.S. 101","y":2024,"id":"2023/22-6389","sc":1,"sum":"For purposes of the Armed Career Criminal Act’s 15-year mandatory minimum sentence on certain defendants with three or more previous convictions, a state drug conviction counts as an ACCA predicate if it involved a drug on the federal schedules at the time of that offense.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"49"}},{"t":"case","label":"Commonwealth v. Martin","cite":"17 Mass. 359","y":1821,"url":"https://www.courtlistener.com/c/Mass./17/359/","by":{"1":"48"}},{"t":"case","label":"Crandon v. United States","cite":"494 U.S. 152","y":1990,"id":"1989/88-931","sc":1,"sum":"Section 209(a) does not apply to a severance payment that is made to encourage the payee to accept Government employment, but is made before the payee becomes a Government employee.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"49"}},{"t":"case","label":"Davis v. United States","cite":"417 U.S. 333","y":1974,"id":"1973/72-1454","sc":1,"sum":"The Court held that Davis could challenge his conviction under 28 U.S.C. Section 2255.","sumSrc":"Oyez","by":{"1":"22"}},{"t":"case","label":"Dillon v. United States","cite":"560 U.S. 817","y":2010,"id":"2009/09-6338","sc":1,"sum":"The Court held that federal sentencing guidelines are binding when a district court imposes a new sentence under a revised guideline range.","sumSrc":"Oyez","by":{"1":"19, 49"}},{"t":"case","label":"Edwards v. Vannoy","cite":"593 U.S. 255","y":2021,"id":"2020/19-5807","sc":1,"sum":"The jury-unanimity rule announced in Ramos v. Louisiana, 590 U. S. ___, does not apply retroactively on federal collateral review.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"33"}},{"t":"case","label":"Foster v. Chatman","cite":"578 U.S. 488","y":2016,"id":"2015/14-8349","sc":1,"sum":"The Court determined that the new evidence in this case was sufficient to establish that there was purposeful discrimination of the type that Batson v. Kentucky prohibits in the jury selection process of Foster’s trial.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"Gonzalez v. Crosby","cite":"545 U.S. 524","y":2005,"id":"2004/04-6432","sc":1,"op":17,"sum":"Holding that only some arguments presented in a Rule 60(b) motion would improperly infringe on § 2254.","sumSrc":"opinion","by":{"1":"37","2":"21, 22"}},{"t":"case","label":"Greenlaw v. United States","cite":"554 U.S. 237","y":2008,"id":"2007/07-330","sc":1,"sum":"The Court stated that the Eighth Circuit could not order the district court to increase Greenlaw's sentence without a request from the government to do so. The Court pointed to several of its precedents for the rule that a remedy in favor the appellee, in this case the government, can only be justified if the appellee brings a cross-appeal.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Hill v. United States","cite":"368 U.S. 424","y":1962,"id":"1961/68","sc":1,"sum":"In a Federal District Court, petitioner was convicted of two federal crimes and sentenced to imprisonment. He was represented by counsel both at the trial and when sentence was imposed; but, before imposing sentence, the judge failed to comply with the requirement of Rule 32 (a) of the Federal Rules of Criminal Procedure that he afford petitioner an opportunity to make a statement in his own behalf. Petitioner took …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"33"}},{"t":"case","label":"Jackson v. Virginia","cite":"443 U.S. 307","y":1979,"id":"1978/78-5283","sc":1,"sum":"Petitioner was convicted of first-degree murder after a bench trial in a Virginia court, and his motion and petition in the state courts to set aside the conviction on the ground that there was insufficient evidence of premeditation, a necessary element of first-degree murder, were denied. He then brought a habeas corpus proceeding in Federal District Court, which, applying the \"no evidence\" criterion of Thompson v. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"46"}},{"t":"case","label":"Jones v. Hendrix","cite":"599 U.S. 465","y":2023,"id":"2022/21-857","sc":1,"op":1,"ar":2,"sum":"The saving clause in 28 U. S. C. §2255(e) does not allow a prisoner asserting an intervening change in the interpretation of a criminal statute to circumvent the Antiterrorism and Effective Death Penalty Act of 1996’s restrictions on second or successive §2255 motions by filing a habeas petition under §2241.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"12, 21, 22, 32, 34, 38"}},{"t":"case","label":"McCarthy v. Madigan","cite":"503 U.S. 140","y":1992,"id":"1991/90-6861","sc":1,"sum":"Exhaustion of the Bureau of Prisons' administrative procedure is not required before a federal prisoner can initiate a Bivens action solely for money damages.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"27"}},{"t":"case","label":"Mistretta v. United States","cite":"488 U.S. 361","y":1989,"id":"1988/87-7028","sc":1,"op":2,"sum":"The Court found the Act to be valid because although Congress cannot generally delegate its legislative power to another Branch, the nondelegation doctrine does not prevent Congress from obtaining assistance from coordinate Branches.","sumSrc":"Oyez","by":{"1":"5"}},{"t":"case","label":"Monsalvo v. Bondi","cite":"145 S. Ct. 1232","y":2025,"id":"2024/23-929","sc":1,"sum":"Under 8 U. S. C. §1229c(b)(2), a voluntary-departure deadline that falls on a weekend or legal holiday extends to the next business day.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"28"}},{"t":"case","label":"Nance v. Ward","cite":"597 U.S. 159","y":2022,"id":"2021/21-439","sc":1,"sum":"Title 42 U. S. C. §1983 is the procedural vehicle appropriate for a prisoner’s method-of-execution claim even if an order granting the relief requested would necessitate a change in state law.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"36, 37","2":"20"}},{"t":"case","label":"Pulsifer v. United States","cite":"601 U.S. 124","y":2024,"id":"2023/22-340","sc":1,"sum":"A criminal defendant facing a mandatory minimum sentence is eligible for safety-valve relief under 18 U. S. C. §3553(f)(1) only if the defendant satisfies each of the provision’s three conditions.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"49"}},{"t":"case","label":"Quarles v. United States","cite":"587 U.S. 645","y":2019,"id":"2018/17-778","sc":1,"sum":"Michigan’s third-degree home-invasion statute substantially corresponds to or is narrower than generic burglary for purposes of qualifying for enhanced sentencing under the Armed Career Criminal Act.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"26"}},{"t":"case","label":"Reno v. Koray","cite":"515 U.S. 50","y":1995,"id":"1994/94-790","sc":1,"sum":"The time respondent spent at the treatment center while \"released\" on bail was not \"official detention\" within the meaning of §3585(b).","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"49"}},{"t":"case","label":"TRW Inc. v. Andrews","cite":"534 U.S. 19","y":2001,"id":"2001/00-1045","sc":1,"sum":"The Court held that a discovery rule does not govern section 1681p of FCRA, as that section explicitly delineated the exceptional case in which discovery triggered the two-year limitation and Adelaide's case does not fall within the exceptional category. The Court reasoned that it was not at liberty to make Congress' explicit exception the general rule.","sumSrc":"Oyez","by":{"1":"39"}},{"t":"case","label":"Tapia v. United States","cite":"564 U.S. 319","y":2011,"id":"2010/10-5400","sc":1,"sum":"The Court held that a district court may not give a defendant a longer prison sentence based on speculation about if and when the defendant would be able to participate in an inmate drug rehabilitation program.","sumSrc":"Oyez","by":{"1":"4, 5, 44"}},{"t":"case","label":"United States v. Booker","cite":"543 U.S. 220","y":2005,"id":"2004/04-104","sc":1,"op":2,"sum":"The Court held that the Sentencing Guidelines, where they allow judges to enhance sentences using facts not reviewed by juries, violated the Sixth Amendment right to trial by jury. The sentences of Booker and Fanfan, based partly on facts determined only by judges, were therefore unconstitutional.","sumSrc":"Oyez","by":{"1":"8, 34"}},{"t":"case","label":"United States v. Bricker","cite":"135 F.4th 427","y":2025,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/135/427/","by":{"1":"44"}},{"t":"case","label":"United States v. Ferguson","cite":"55 F.4th 262","y":2022,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/55/262/","op":1,"by":{"1":"35","2":"17"}},{"t":"case","label":"United States v. Havener","cite":"905 F.2d 3","y":1990,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/905/3/","by":{"1":"30"}},{"t":"case","label":"United States v. Hunter","cite":"12 F.4th 555","y":2021,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/12/555/","by":{"1":"35"}},{"t":"case","label":"United States v. Jarvis","cite":"999 F.3d 442","y":2021,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/999/442/","by":{"1":"47"}},{"t":"case","label":"United States v. King","cite":"40 F.4th 594","y":2022,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/40/594/","by":{"1":"22, 23"}},{"t":"case","label":"United States v. Smith","cite":"650 F.2d 206","y":1981,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/650/206/","by":{"1":"25"}},{"t":"case","label":"United States v. Trenkler","cite":"47 F.4th 42","y":2022,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.4th/47/42/","op":1,"by":{"1":"28, 35","2":"8, 22"}},{"t":"case","label":"United States v. Von Vader","cite":"58 F.4th 369","y":2023,"url":"https://www.courtlistener.com/c/F.4th/58/369/","op":1,"by":{"1":"35"}},{"t":"case","label":"United States v. Wesley: 60 F.4th 177 (10th Cir. 2023), cert. denied","cite":"144 S. Ct. 2649","y":2024,"url":"https://www.courtlistener.com/c/S.%20Ct./144/2649/","sc":1,"op":1,"by":{"1":"26"}},{"t":"case","label":"West Va. Univ. Hosps., Inc. v. Casey","cite":"499 U.S. 83","y":1991,"id":"1990/89-994","sc":1,"op":1,"sum":"Fees for services rendered by experts in civil rights litigation may not be shifted to the losing party as part of \"a reasonable attorney's fee\" under § 1988.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"38"}},{"t":"case","label":"Whitman v. American Trucking Ass’ns","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"sum":"The Court held that the CAA properly delegated legislative power to the EPA, but that the EPA could not consider implementation costs in setting primary and secondary NAAQS.","sumSrc":"Oyez","by":{"1":"38"}},{"t":"case","label":"Wisconsin Cent. Ltd. v. United States","cite":"585 U.S. 274","y":2018,"id":"2017/17-530","sc":1,"sum":"The Court decided that employee stock options are not taxable “compensation” under the Railroad Retirement Tax Act because they are not “money remuneration.”","sumSrc":"Oyez","by":{"1":"20"}},{"t":"const","label":"Amendment VI","clauses":[["sixth-trial","Speedy and Public Trial by Jury"],["confrontation","Confrontation Clause"],["counsel","Right to Counsel"]],"text":"In all criminal prosecutions, the accused shall enjoy the right to a speedy and public trial, by an impartial jury of the State and district wherein the crime shall have been committed, which district shall have been previously ascertained by law, and to be informed of the nature and cause of the accusation; to be confronted with the witnesses against him; to have compulsory process for obtaining witnesses in his favor, and to have the Assistance of Counsel for his defence.","by":{"1":"35"}},{"t":"usc","label":"18 U.S.C. § 3551","url":"https://www.law.cornell.edu/uscode/text/18/3551","by":{"1":"5"}},{"t":"usc","label":"18 U.S.C. § 3553","url":"https://www.law.cornell.edu/uscode/text/18/3553","subs":["(a)","(b)"],"by":{"1":"4, 10, 12, 13, 22, 4, 10, 12, 13, 22"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","stext":{"head":"§924. Penalties","paras":[[0,"(a)(1) Except as otherwise provided in this subsection, subsection (b), (c), (f), or (p) of this section, or in section 929, whoever—"],[1,"(A) knowingly makes any false statement or representation with respect to the information required by this chapter to be kept in the records of a person licensed under this chapter or in applying for any license or exemption or relief from disability under the provisions of this chapter;"],[1,"(B) knowingly violates subsection (a)(4), (f), (k), or (q) of section 922;"],[1,"(C) knowingly imports or brings into the United States or any possession thereof any firearm or ammunition in violation of section 922(l); or"],[1,"(D) willfully violates any other provision of this chapter,"],[0,"shall be fined under this title, imprisoned not more than five years, or both."],[0,"(2) Whoever knowingly violates subsection (a)(6), (h), (i), (j), or (o) of section 922 shall be fined as provided in this title, imprisoned not more than 10 years, or both."],[0,"(3) Any licensed dealer, licensed importer, licensed manufacturer, or licensed collector who knowingly—"],[1,"(A) makes any false statement or representation with respect to the information required by the provisions of this chapter to be kept in the records of a person licensed under this chapter, or"],[1,"(B) violates subsection (m) of section 922,"],[0,"shall be fined under this title, imprisoned not more than one year, or both."],[0,"(4) Whoever violates section 922(q) shall be fined under this title, imprisoned for not more than 5 years, or both. Notwithstanding any other provision of law, the term of imprisonment imposed under this paragraph shall not run concurrently with any other term of imprisonment imposed under any other provision of law. Except for the authorization of a term of imprisonment of not more than 5 years made in this paragraph, for the purpose of any other law a violation of section 922(q) shall be deemed to be a misdemeanor."],[0,"(5) Whoever knowingly violates subsection (s) or (t) of section 922 shall be fined under this title, imprisoned for not more than 1 year, or both."],[0,"(6)(A)(i) A juvenile who violates section 922(x) shall be fined under this title, imprisoned not more than 1 year, or both, except that a juvenile described in clause (ii) shall be sentenced to probation on appropriate conditions and shall not be incarcerated unless the juvenile fails to comply with a condition of probation."],[0,"(ii) A juvenile is described in this clause if—"],[1,"(I) the offense of which the juvenile is charged is possession of a handgun or ammunition in violation of section 922(x)(2); and"],[1,"(II) the juvenile has not been convicted in any court of an offense (including an offense under section 922(x) or a similar State law, but not including any other offense consisting of conduct that if engaged in by an adult would not constitute an offense) or adjudicated as a juvenile delinquent for conduct that if engaged in by an adult would constitute an offense."],[0,"(B) A person other than a juvenile who knowingly violates section 922(x)—"],[1,"(i) shall be fined under this title, imprisoned not more than 1 year, or both; and"],[1,"(ii) if the person sold, delivered, or otherwise transferred a handgun or ammunition to a juvenile knowing or having reasonable cause to know that the juvenile intended to carry or otherwise possess or discharge or otherwise use the handgun or ammunition in the commission of a crime of violence, shall be fined under this title, imprisoned not more than 10 years, or both."],[0,"(7) Whoever knowingly violates section 931 shall be fined under this title, imprisoned not more than 3 years, or both."],[0,"(8) Whoever knowingly violates subsection (d) or (g) of section 922 shall be fined under this title, imprisoned for not more than 15 years, or both."],[0,"(b) Whoever, with intent to commit therewith an offense punishable by imprisonment for a term exceeding one year, or with knowledge or reasonable cause to believe that an offense punishable by imprisonment for a term exceeding one year is to be committed therewith, ships, transports, or receives a firearm or any ammunition in interstate or foreign commerce shall be fined under this title, or imprisoned not more than ten years, or both."],[0,"(c)(1)(A) Except to the extent that a greater minimum sentence is otherwise provided by this subsection or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries a firearm, or who, in furtherance of any such crime, possesses a firearm, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime—"],[1,"(i) be sentenced to a term of imprisonment of not less than 5 years;"],[1,"(ii) if the firearm is brandished, be sentenced to a term of imprisonment of not less than 7 years; and"],[1,"(iii) if the firearm is discharged, be sentenced to a term of imprisonment of not less than 10 years."],[0,"(B) If the firearm possessed by a person convicted of a violation of this subsection—"],[1,"(i) is a short-barreled rifle, short-barreled shotgun, or semiautomatic assault weapon, the person shall be sentenced to a term of imprisonment of not less than 10 years; or"],[1,"(ii) is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, the person shall be sentenced to a term of imprisonment of not less than 30 years."],[0,"(C) In the case of a violation of this subsection that occurs after a prior conviction under this subsection has become final, the person shall—"],[1,"(i) be sentenced to a term of imprisonment of not less than 25 years; and"],[1,"(ii) if the firearm involved is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, be sentenced to imprisonment for life."],[0,"(D) Notwithstanding any other provision of law—"],[1,"(i) a court shall not place on probation any person convicted of a violation of this subsection; and"],[1,"(ii) no term of imprisonment imposed on a person under this subsection shall run concurrently with any other term of imprisonment imposed on the person, including any term of imprisonment imposed for the crime of violence or drug trafficking crime during which the firearm was used, carried, or possessed."],[0,"(2) For purposes of this subsection, the term \"drug trafficking crime\" means any felony punishable under the Controlled Substances Act (21 U.S.C. 801 et seq.), the Controlled Substances Import and Export Act (21 U.S.C. 951 et seq.), or chapter 705 of title 46."],[0,"(3) For purposes of this subsection the term \"crime of violence\" means an offense that is a felony and—"],[1,"(A) has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(B) that by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."],[0,"(4) For purposes of this subsection, the term \"brandish\" means, with respect to a firearm, to display all or part of the firearm, or otherwise make the presence of the firearm known to another person, in order to intimidate that person, regardless of whether the firearm is directly visible to that person."],[0,"(5) Except to the extent that a greater minimum sentence is otherwise provided under this subsection, or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries armor piercing ammunition, or who, in furtherance of any such crime, possesses armor piercing ammunition, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime or conviction under this section—"],[1,"(A) be sentenced to a term of imprisonment of not less than 15 years; and"],[1,"(B) if death results from the use of such ammunition—"],[2,"(i) if the killing is murder (as defined in section 1111), be punished by death or sentenced to a term of imprisonment for any term of years or for life; and"],[2,"(ii) if the killing is manslaughter (as defined in section 1112), be punished as provided in section 1112."],[0,"(d)(1) Any firearm or ammunition involved in or used in any knowing violation of subsection (a)(4), (a)(6), (f), (g), (h), (i), (j), or (k) of section 922, or knowing importation or bringing into the United States or any possession thereof any firearm or ammunition in violation of section 922(l), or knowing violation of section 924, 932, or 933, or willful violation of any other provision of this chapter or any rule or regulation promulgated thereunder, or any violation of any other criminal law of the United States, or any firearm or ammunition intended to be used in any offense referred to in paragraph (3) of this subsection, where such intent is demonstrated by clear and convincing evidence, shall be subject to seizure and forfeiture, and all provisions of the Internal Revenue Code of 1986 relating to the seizure, forfeiture, and disposition of firearms, as defined in section 5845(a) of that Code, shall, so far as applicable, extend to seizures and forfeitures under the provisions of this chapter: Provided, That upon acquittal of the owner or possessor, or dismissal of the charges against him other than upon motion of the Government prior to trial, or lapse of or court termination of the restraining order to which he is subject, the seized or relinquished firearms or ammunition shall be returned forthwith to the owner or possessor or to a person delegated by the owner or possessor unless the return of the firearms or ammunition would place the owner or possessor or his delegate in violation of law. Any action or proceeding for the forfeiture of firearms or ammunition shall be commenced within one hundred and twenty days of such seizure."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/924?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§924. Penalties","tname":"Crimes and Criminal Procedure","by":{"1":"4, 10, 12, 13, 22"}},{"t":"usc","label":"18 U.S.C. § 1958","url":"https://www.law.cornell.edu/uscode/text/18/1958","by":{"1":"4, 10"}},{"t":"usc","label":"18 U.S.C. § 4042","url":"https://www.law.cornell.edu/uscode/text/18/4042","subs":["(a)"],"stext":{"head":"§4042. Duties of Bureau of Prisons","paras":[[0,"(a) In General.—The Bureau of Prisons, under the direction of the Attorney General, shall—"],[1,"(1) have charge of the management and regulation of all Federal penal and correctional institutions;"],[1,"(2) provide suitable quarters and provide for the safekeeping, care, and subsistence of all persons charged with or convicted of offenses against the United States, or held as witnesses or otherwise;"],[1,"(3) provide for the protection, instruction, and discipline of all persons charged with or convicted of offenses against the United States;"],[1,"(4) provide technical assistance to State, tribal, and local governments in the improvement of their correctional systems;"],[1,"(5) provide notice of release of prisoners in accordance with subsections (b) and (c);"],[1,"(6) establish prerelease planning procedures that help prisoners—"],[2,"(A) apply for Federal and State benefits upon release (including Social Security benefits, and veterans' benefits);"],[2,"(B) obtain identification, including a social security card, driver's license or other official photo identification, and a birth certificate; and"],[2,"(C) secure such identification and benefits prior to release from a sentence to a term of imprisonment in a Federal prison or if the individual was not sentenced to a term of imprisonment in a Federal prison, prior to release from a sentence to a term of community confinement, subject to any limitations in law; and"],[1,"(7) establish reentry planning procedures that include providing Federal prisoners with information in the following areas:"],[2,"(A) Health and nutrition."],[2,"(B) Employment."],[2,"(C) Literacy and education."],[2,"(D) Personal finance and consumer skills."],[2,"(E) Community resources."],[2,"(F) Personal growth and development."],[2,"(G) Release requirements and procedures."],[0,"(b) Notice of Release of Prisoners.—(1) At least 5 days prior to the date on which a prisoner described in paragraph (3) is to be released on supervised release, or, in the case of a prisoner on supervised release, at least 5 days prior to the date on which the prisoner changes residence to a new jurisdiction, written notice of the release or change of residence shall be provided to the chief law enforcement officers of each State, tribal, and local jurisdiction in which the prisoner will reside. Notice prior to release shall be provided by the Director of the Bureau of Prisons. Notice concerning a change of residence following release shall be provided by the probation officer responsible for the supervision of the released prisoner, or in a manner specified by the Director of the Administrative Office of the United States Courts. The notice requirements under this subsection do not apply in relation to a prisoner being protected under chapter 224."],[0,"(2) A notice under paragraph (1) shall disclose—"],[1,"(A) the prisoner's name;"],[1,"(B) the prisoner's criminal history, including a description of the offense of which the prisoner was convicted; and"],[1,"(C) any restrictions on conduct or other conditions to the release of the prisoner that are imposed by law, the sentencing court, or the Bureau of Prisons or any other Federal agency."],[0,"(3) A prisoner is described in this paragraph if the prisoner was convicted of—"],[1,"(A) a drug trafficking crime, as that term is defined in section 924(c)(2); or"],[1,"(B) a crime of violence (as defined in section 924(c)(3))."],[0,"(c) Notice of Sex Offender Release.—(1) In the case of a person described in paragraph (3), or any other person in a category specified by the Attorney General, who is released from prison or sentenced to probation, notice shall be provided to—"],[1,"(A) the chief law enforcement officer of each State, tribal, and local jurisdiction in which the person will reside; and"],[1,"(B) a State, tribal, or local agency responsible for the receipt or maintenance of sex offender registration information in the State, tribal, or local jurisdiction in which the person will reside."],[0,"The notice requirements under this subsection do not apply in relation to a person being protected under chapter 224."],[0,"(2) Notice provided under paragraph (1) shall include the information described in subsection (b)(2), the place where the person will reside, and the information that the person shall register as required by the Sex Offender Registration and Notification Act. For a person who is released from the custody of the Bureau of Prisons whose expected place of residence following release is known to the Bureau of Prisons, notice shall be provided at least 5 days prior to release by the Director of the Bureau of Prisons. For a person who is sentenced to probation, notice shall be provided promptly by the probation officer responsible for the supervision of the person, or in a manner specified by the Director of the Administrative Office of the United States Courts. Notice concerning a subsequent change of residence by a person described in paragraph (3) during any period of probation, supervised release, or parole shall also be provided to the agencies and officers specified in paragraph (1) by the probation officer responsible for the supervision of the person, or in a manner specified by the Director of the Administrative Office of the United States Courts."],[0,"(3) The Director of the Bureau of Prisons shall inform a person who is released from prison and required to register under the Sex Offender Registration and Notification Act of the requirements of that Act as they apply to that person and the same information shall be provided to a person sentenced to probation by the probation officer responsible for supervision of that person."],[0,"[(4) Repealed. Pub. L. 109–248, title I, §141(h), July 27, 2006, 120 Stat. 604.]"],[0,"(5) The United States and its agencies, officers, and employees shall be immune from liability based on good faith conduct in carrying out this subsection and subsection (b)."],[0,"(d) Application of Section.—This section shall not apply to military or naval penal or correctional institutions or the persons confined therein."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/4042?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§4042. Duties of Bureau of Prisons","tname":"Crimes and Criminal Procedure","by":{"1":"26"}},{"t":"usc","label":"18 U.S.C. § 4205","url":"https://www.law.cornell.edu/uscode/text/18/4205","subs":["(a)(1982)","(b)(1982)","(g)(1982)"],"by":{"1":"37, 38, 37, 38, 37, 38"}},{"t":"usc","label":"28 U.S.C. § 2241","url":"https://www.law.cornell.edu/uscode/text/28/2241","by":{"1":"37, 38"}},{"t":"reg","label":"59 Fed. Reg. 1238","url":"https://www.govinfo.gov/link/fr/59/1238","by":{"1":"30"}},{"t":"case","label":"Ali v. Fed. Bureau of Prisons","cite":"552 U.S. 214","y":2008,"id":"2007/06-9130","sc":1,"op":20,"ar":5,"sum":"The Court agreed with the 11th Circuit and, in a 5-4 majority opinion written by Justice Clarence Thomas, held that the use of the word \"any\" should be given its normal interpretation, encompassing all federal officers whether or not they were involved in enforcing customs or excise laws.","sumSrc":"Oyez","by":{"2":"17"}},{"t":"case","label":"Carcieri v. Salazar","cite":"555 U.S. 379","y":2009,"id":"2008/07-526","sc":1,"sum":"The Court found that only tribes under federal jurisdiction at the time of the Indian Reorganization Act of 1934 are subject to taking by the federal government.","sumSrc":"Oyez","by":{"2":"15"}},{"t":"case","label":"Morton v. Mancari","cite":"417 U.S. 535","y":1974,"id":"1973/73-362","sc":1,"sum":"In addition, the Court held that Section 472 did not constitute discrimination in violation of the Fifth Amendment. Again, Justice Blackmun cited the history of \"special treatment\" granted to Indians.","sumSrc":"Oyez","by":{"2":"19"}},{"t":"case","label":"Nichols v. United States","cite":"578 U.S. 104","y":2016,"id":"2015/15-5238","sc":1,"sum":"The Court determined that the Sexual Offender Registration and Notification Act does not require a sex offender who is moving to a country outside of U.S. jurisdiction to update his residence with the sexual offender registry.","sumSrc":"Oyez","by":{"2":"18"}},{"t":"case","label":"United States v. Batchelder","cite":"442 U.S. 114","y":1979,"id":"1978/78-776","sc":1,"sum":"A defendant convicted of violating § 922 (h) is properly sentenced under § 924 (a) even though his conduct also violates § 1202 (a).","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"24"}},{"t":"case","label":"United States v. Conley","cite":"2021 WL 825669","y":2021,"court":"N.D. Ill. Mar. 4","by":{"2":"10"}},{"t":"case","label":"United States v. Liscano","cite":"2021 WL 4413320","y":2021,"court":"N.D. Ill. Sept. 27","sum":"Finding extraordinary and compelling reasons based, in part, on defendant serving a life sentence that the government conceded was unlawfully imposed.","sumSrc":"brief:2","by":{"2":"8"}},{"t":"case","label":"United States v. Trenkler","cite":"537 F. Supp. 3d 91","y":2021,"court":"D. Mass.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/537/91/","by":{"2":"8"}},{"t":"rule","label":"Fed. R. Civ. P. 60","url":"https://www.law.cornell.edu/rules/frcp/rule_60","subs":["(b)"],"by":{"2":"21, 22"}},{"t":"rule","label":"Fed. R. Crim. P. 35","url":"https://www.law.cornell.edu/rules/frcrmp/rule_35","by":{"2":"16"}}]};